<?php declare(strict_types=1);namespace App\Modules\ContractBoq\Controllers;use App\Core\Exceptions\BusinessRuleException;use App\Core\Exceptions\ValidationException;use App\Core\Http\Csrf;use App\Core\Http\Request;use App\Core\Http\Response;use App\Core\View\View;use App\Modules\AccessControl\Services\AuthorizationService;
use App\Modules\ContractBoq\Services\ContractBoqService;
use App\Modules\ContractBoq\Validators\BoqItemValidator;
use App\Modules\ContractBoq\Validators\BoqSectionValidator;
final class ContractBoqController{
    public function __construct(private readonly View$v,private readonly Csrf$csrf,private readonly AuthorizationService$auth,private readonly ContractBoqService$s,private readonly BoqSectionValidator$sv,private readonly BoqItemValidator$iv){}public function show(Request$r):Response{$d=$this->s->page((int)$r->route('contract_id'));return Response::html($this->v->render('modules/contract-boq/show',['title'=>'جدول الكميات ونطاق الأعمال',...$d,'canManage'=>$this->auth->can('contract_boq.manage'),'canApprove'=>$this->auth->can('contract_boq.approve')]));}public function start(Request$r):Response{return$this->run($r,fn()=>$this->s->start((int)$r->route('contract_id')));}public function section(Request$r):Response{return$this->run($r,fn()=>$this->s->saveSection((int)$r->route('contract_id'),$this->sv->validate($r->all()),$r->route('section_id')?(int)$r->route('section_id'):null));}public function item(Request$r):Response{return$this->run($r,fn()=>$this->s->saveItem((int)$r->route('contract_id'),$this->iv->validate($r->all()),$r->route('item_id')?(int)$r->route('item_id'):null));}public function removeSection(Request$r):Response{return$this->run($r,fn()=>$this->s->removeSection((int)$r->route('contract_id'),(int)$r->route('section_id')));}public function removeItem(Request$r):Response{return$this->run($r,fn()=>$this->s->removeItem((int)$r->route('contract_id'),(int)$r->route('item_id')));}public function approve(Request$r):Response{return$this->run($r,fn()=>$this->s->approve((int)$r->route('contract_id')));}public function discard(Request$r):Response{return$this->run($r,fn()=>$this->s->discard((int)$r->route('contract_id')));}private function run(Request$r,callable$f):Response{if(!$this->csrf->isValid($r->input('_token')))return Response::json(['message'=>'انتهت صلاحية الطلب.'],419);try{$f();return Response::json(['message'=>'تم حفظ التغييرات.']);}catch(ValidationException$e){return Response::json(['message'=>'يرجى مراجعة البيانات.','errors'=>$e->errors],422);}catch(BusinessRuleException$e){return Response::json(['message'=>$e->getMessage()],400);}}
}
